"""Read pickle contents WITHOUT executing anything.

Simulates the pickle stack machine but replaces every GLOBAL/REDUCE with an
inert placeholder, so no module is imported and no callable is invoked.
"""
import pickletools, json

class Inert:
    def __init__(self, kind, detail): self.kind, self.detail = kind, detail
    def __repr__(self): return f'<{self.kind}: {self.detail}>'

def inert_load(path):
    stack, memo = [], {}
    for op, arg, pos in pickletools.genops(open(path, 'rb')):
        n = op.name
        if n in ('SHORT_BINUNICODE','BINUNICODE','UNICODE'):      stack.append(arg)
        elif n in ('SHORT_BINSTRING','BINSTRING','STRING'):        stack.append(arg)
        elif n in ('SHORT_BINBYTES','BINBYTES','BINBYTES8'):       stack.append(arg)
        elif n == 'BINFLOAT':                                      stack.append(arg)
        elif n in ('BININT','BININT1','BININT2','LONG','LONG1'):   stack.append(arg)
        elif n == 'FLOAT':                                         stack.append(float(arg))
        elif n == 'NONE':                                          stack.append(None)
        elif n == 'NEWTRUE':                                       stack.append(True)
        elif n == 'NEWFALSE':                                      stack.append(False)
        elif n in ('EMPTY_DICT',):                                 stack.append({})
        elif n in ('EMPTY_LIST',):                                 stack.append([])
        elif n in ('EMPTY_TUPLE',):                                stack.append(())
        elif n in ('EMPTY_SET',):                                  stack.append(set())
        elif n == 'MARK':                                          stack.append(Inert('mark',''))
        elif n == 'MEMOIZE':                                       memo[len(memo)] = stack[-1]
        elif n in ('BINGET','LONG_BINGET','GET'):                  stack.append(memo[arg])
        elif n in ('PUT','BINPUT','LONG_BINPUT'):                  memo[arg] = stack[-1]
        elif n == 'STACK_GLOBAL':
            nm = stack.pop(); md = stack.pop()
            stack.append(Inert('global', f'{md}.{nm}'))            # NOT imported
        elif n == 'GLOBAL':
            stack.append(Inert('global', arg.replace(' ', '.')))   # NOT imported
        elif n in ('REDUCE','OBJ','INST','NEWOBJ','NEWOBJ_EX'):
            args = stack.pop(); fn = stack.pop()
            stack.append(Inert('reduced', f'{fn}({args!r})'))      # NOT called
        elif n == 'BUILD':
            if isinstance(stack[-1], Inert): stack.pop()
        elif n in ('TUPLE','TUPLE1','TUPLE2','TUPLE3'):
            cnt = 1 if n=='TUPLE1' else 2 if n=='TUPLE2' else 3 if n=='TUPLE3' else None
            if cnt is None:
                i = len(stack)-1
                while not isinstance(stack[i], Inert) or stack[i].kind!='mark': i -= 1
                items = stack[i+1:]; del stack[i:]
            else:
                items = stack[len(stack)-cnt:] if cnt else []
                del stack[len(stack)-cnt:] if cnt else None
                items = stack[len(stack):] if False else items
            stack.append(tuple(items))
        elif n in ('SETITEMS','APPENDS','LIST','DICT','SETITEM'):
            if n == 'SETITEM':
                v = stack.pop(); k = stack.pop(); stack[-1][k] = v; continue
            i = len(stack)-1
            while not (isinstance(stack[i], Inert) and stack[i].kind=='mark'): i -= 1
            items = stack[i+1:]; del stack[i:]
            tgt = stack[-1]
            if n in ('SETITEMS','DICT'):
                for k, v in zip(items[::2], items[1::2]): tgt[k] = v
            elif n == 'APPENDS':
                tgt.extend(items)
            elif n == 'LIST':
                stack.append(list(items))
        elif n == 'STOP':
            break
    return stack[-1] if stack else None

rows = []
man = json.load(open('/tmp/models.json'))
id_by_file = {e['file']: e for e in man['models']}

for i in ['01','02','03','04','05','06','07','08','09','10']:
    p = f'model_{i}.pkl'
    obj = inert_load(p)
    entry = id_by_file[p]
    scalars = {k: v for k, v in obj.items() if not isinstance(v, (dict, list, tuple, Inert))}
    inert_keys = {k: v for k, v in obj.items() if isinstance(v, Inert) or k == 'extra_state'}
    rows.append((entry['id'], entry['contributor'], scalars.get('val_accuracy'), p, scalars))
    match = scalars.get('id') == entry['id']
    print(f'{p}: id={scalars.get("id")!r} (manifest {entry["id"]}, match={match}) '
          f'val_accuracy={scalars.get("val_accuracy")!r} epochs={scalars.get("epochs")!r} '
          f'framework={scalars.get("framework")!r}')
    for k, v in inert_keys.items():
        print(f'      extra key {k!r} -> {v!r}')

print()
json.dump([[r[0], r[2]] for r in rows], open('/tmp/scores.json','w'))
print('wrote /tmp/scores.json')
